PyObject *
PyAnariAttributes_getattro(PyObject *self, PyObject *attr_name)
{
    const char *name = PyUnicode_AsUTF8(attr_name);
    if (!name) return NULL;

    if(strcmp(name, "anariRendering") == 0)
        return AnariAttributes_GetAnariRendering(self, NULL);
    if(strcmp(name, "anariLibrary") == 0)
        return AnariAttributes_GetAnariLibrary(self, NULL);
    if(strcmp(name, "anariLibrarySubtype") == 0)
        return AnariAttributes_GetAnariLibrarySubtype(self, NULL);
    if(strcmp(name, "anariRendererSubtype") == 0)
        return AnariAttributes_GetAnariRendererSubtype(self, NULL);
    if(strcmp(name, "usingUsdDevice") == 0)
        return AnariAttributes_GetUsingUsdDevice(self, NULL);
    if(strcmp(name, "anariRendererParameters") == 0)
        return AnariAttributes_GetAnariRendererParameters(self, NULL);
    if(strcmp(name, "anariUSDParameters") == 0)
        return AnariAttributes_GetAnariUSDParameters(self, NULL);

    PyObject *meth = Py_FindMethod(PyAnariAttributes_methods, self, (char*)name);
    if (meth) return meth;

    return PyObject_GenericGetAttr(self, attr_name);
}

int
PyAnariAttributes_setattro(PyObject *self, PyObject *attr_name, PyObject *args)
{
    PyObject NULL_PY_OBJ;
    PyObject *obj = &NULL_PY_OBJ;
    const char *name = PyUnicode_AsUTF8(attr_name);
    if (!name) return -1;

    if(strcmp(name, "anariRendering") == 0)
        obj = AnariAttributes_SetAnariRendering(self, args);
    else if(strcmp(name, "anariLibrary") == 0)
        obj = AnariAttributes_SetAnariLibrary(self, args);
    else if(strcmp(name, "anariLibrarySubtype") == 0)
        obj = AnariAttributes_SetAnariLibrarySubtype(self, args);
    else if(strcmp(name, "anariRendererSubtype") == 0)
        obj = AnariAttributes_SetAnariRendererSubtype(self, args);
    else if(strcmp(name, "usingUsdDevice") == 0)
        obj = AnariAttributes_SetUsingUsdDevice(self, args);
    else if(strcmp(name, "anariRendererParameters") == 0)
        obj = AnariAttributes_SetAnariRendererParameters(self, args);
    else if(strcmp(name, "anariUSDParameters") == 0)
        obj = AnariAttributes_SetAnariUSDParameters(self, args);

    if (obj == &NULL_PY_OBJ && PyObject_GenericSetAttr(self, attr_name, args) == 0)
    {
        Py_INCREF(Py_None);
        obj = Py_None;
    }

    if (obj != NULL && obj != &NULL_PY_OBJ)
        Py_DECREF(obj);

    if (obj == &NULL_PY_OBJ)
    {
        obj = NULL;
        PyErr_Format(PyExc_NameError, "name '%s' is not defined", name);
    }
    else if (obj == NULL && !PyErr_Occurred())
        PyErr_Format(PyExc_RuntimeError, "unknown problem with '%s'", name);

    return (obj != NULL) ? 0 : -1;
}

